class StockCount
  attr_reader :count

  def initialize(count)
    @count = count.to_i
  end

  def -(other)
    if other.is_a?(StockCount)
      @count.to_f - other.count.to_f
    elsif other.is_a?(Rational)
      @count.to_f - other.to_f
    else
      raise ArgumentError, "Unsupported subtraction type for #{other.class}"
    end
  end

  def ==(other)
    if other.is_a?(StockCount)
      self.count == other.count
    else
      false
    end
  end
end
