class SparseArray
  # Initializes a new SparseArray.
  # @param initial_array [Array, nil] An optional array to initialize with.
  #   If provided, it populates the array using []= syntax.
  #   Returns a SparseArray instance.
  def initialize(initial_array = nil)
    @storage = {}
    if initial_array.is_a?(Array)
      initial_array.each_with_index { |(value, index)| []=(index, value) }
    end
  end

  # Sets the value at the given index.
  # @param index [Integer] The index to set.
  # @param value [Object] The value to store.
  def []=(index, value)
    @storage[index] = value
  end

  # Retrieves the value at the given index.
  # @param index [Integer] The index to look up.
  # @return [Object, nil] The stored value, or nil if the index is not set.
  def [](index)
    @storage[index]
  end

  # Enumerates over the stored values in ascending index order.
  # This allows the object to be enumerable.
  # @return [Enumerable] An enumerator yielding values.
  def each(&block)
    # Iterate through keys (indexes) in sorted order.
    @storage.keys.sort.each(&block) do |index|
      # Yield the stored value.
      yield @storage[index]
    end
  end

  # Returns the count of elements stored.
  # @return [Integer] The number of stored elements.
  def count
    @storage.size
  end

  # Provides a map equivalent to Array#map, yielding a new array.
  # Applies the block to each stored value.
  # @param block [Proc] The transformation block.
  # @return [Array] A new array with transformed values.
  def map(&block)
    @storage.keys.sort.map { |index| instance_exec(&block) }
  end

  # Provides a select equivalent to Array#select, yielding a new array.
  # Applies the block to each stored value, keeping only those that return true.
  # @param block [Proc] The predicate block.
  # @return [Array] A new array containing selected values.
  def select(&block)
    @storage.keys.sort.select { |index| instance_exec(&block) }
  end

  # Provides a sum equivalent to Array#sum (assuming numeric values).
  # @return [Numeric] The sum of all stored values.
  def sum
    @storage.values.sum
  end
end
